#include "station.h"
static unsigned le16(const uint8_t*p){return p[0]|((unsigned)p[1]<<8);}
static uint32_t le32(const uint8_t*p){return le16(p)|((uint32_t)le16(p+2)<<16);}
static int same(const uint8_t*a,const uint8_t*b,unsigned n){for(unsigned j=0;j<n;j++)if(a[j]!=b[j])return 0;return 1;}
static int mac(const uint8_t*p){unsigned x=0;for(unsigned j=0;j<6;j++)x|=p[j];return x&&!(p[0]&1);}
static int overlap(const void*a,unsigned n,const void*b,unsigned m){uintptr_t x=(uintptr_t)a,y=(uintptr_t)b;return x>UINTPTR_MAX-n||y>UINTPTR_MAX-m||(x<y?y-x<n:x-y<m);}
static int frame(const QcaRxEvent*e,unsigned pipe,unsigned endpoint,QcaHtcFrame*h){return e&&e->completion&&e->pipe==pipe&&e->endpoint==endpoint&&endpoint&&endpoint<9&&e->raw_bytes>=8&&e->raw_bytes<=2048&&qca_htc_decode(e->raw,e->raw_bytes,h)&&h->endpoint==endpoint&&h->payload_bytes==e->bytes;}
int sta_decode_htt(const QcaRxEvent*e,uint8_t endpoint,StaEvent*out){
 if(!out||!e||overlap(out,sizeof(*out),e,sizeof(*e)))return -1;QcaHtcFrame h={0};if(!frame(e,1,endpoint,&h)||e->event||!h.payload_bytes)return -1;const uint8_t*p=h.payload;StaEvent v={0};v.completion=e->completion;
 if(p[0]==3){if(h.payload_bytes!=12||!mac(p+4))return -1;v.kind=STA_PEER_MAP;v.vdev=p[1];v.peer_id=(uint16_t)le16(p+2);for(unsigned j=0;j<6;j++)v.peer[j]=p[4+j];}
 else if(p[0]==4){if(h.payload_bytes!=4)return -1;v.kind=STA_PEER_UNMAP;v.peer_id=(uint16_t)le16(p+2);}
 else if(p[0]==11){if(h.payload_bytes!=28)return -1;v.kind=STA_SEC_IND;v.cipher=p[1]&127;v.unicast=p[1]>>7;v.peer_id=(uint16_t)le16(p+2);}
 else return 0;*out=v;return 1;
}
int sta_decode_htt_bound(const QcaRxEvent*e,const QcaHttBinding*b,const QcaHttVersion*v,StaEvent*out){if(!e||!b||!v||!out||b->op_version!=3||v->major!=3||v->minor!=56||b->max_bytes<e->bytes||overlap(out,sizeof(*out),b,sizeof(*b))||overlap(out,sizeof(*out),v,sizeof(*v)))return -1;return sta_decode_htt(e,b->endpoint,out);}
static int rates(const uint8_t*p,unsigned n,uint16_t native,uint16_t*out){unsigned at=0,seen=0,ext=0;uint16_t all=0,basic=0;uint8_t raw[32]={0};unsigned count=0;static const uint8_t known[]={2,4,11,22,12,18,24,36,48,72,96,108};while(at<n){if(n-at<2)return 0;unsigned id=p[at++],len=p[at++];if(len>n-at)return 0;if(id==1||id==50){if(!len||len>32-count||(id==1&&(seen++||len>8))||(id==50&&ext++))return 0;for(unsigned j=0;j<len;j++){unsigned r=p[at+j]&127;for(unsigned k=0;k<count;k++)if(raw[k]==r)return 0;raw[count++]=(uint8_t)r;unsigned bit=0;for(unsigned k=0;k<12;k++)if(known[k]==r)bit=1u<<k;if(!r||(!bit&&(p[at+j]&128)))return 0;all|=(uint16_t)bit;if(p[at+j]&128)basic|=(uint16_t)bit;}}at+=len;}if(seen!=1||!basic||!all||(basic&~native))return 0;*out=all&native;return *out!=0;}
int sta_decode_mgmt(const QcaRxEvent*e,uint8_t endpoint,uint32_t frequency,const uint8_t peer[6],const uint8_t own[6],uint16_t native,StaEvent*out){
 if(!e||!out||!peer||!own||!mac(peer)||!mac(own)||!native||(native&~0xfffu)||overlap(out,sizeof(*out),e,sizeof(*e))||overlap(out,sizeof(*out),peer,6)||overlap(out,sizeof(*out),own,6))return -1;
 QcaHtcFrame h={0};if(!frame(e,2,endpoint,&h)||h.payload_bytes<4||e->event!=le32(h.payload))return -1;if((e->event&0xffffff)!=0x7001)return 0;
 const uint8_t*hdr=0,*f=0;unsigned span=0;for(unsigned at=4;at<h.payload_bytes;){if(h.payload_bytes-at<4)return -1;unsigned n=le16(h.payload+at),tag=le16(h.payload+at+2);at+=4;if(n>h.payload_bytes-at)return -1;if(tag==44){if(hdr||n!=40)return -1;hdr=h.payload+at;}else if(tag==17){if(f)return -1;f=h.payload+at;span=n;}else return -1;at+=n;}
 if(!hdr||!f||le32(hdr+20)||le32(hdr)<1||le32(hdr)>13||2407+5*le32(hdr)!=frequency)return -1;unsigned n=le32(hdr+16);if(n<26||n>span||(span!=n&&span!=((n+3)&~3u)))return -1;for(unsigned j=n;j<span;j++)if(f[j])return -1;
 unsigned fc=le16(f);if((fc&0xc707)||!same(f+4,own,6)||!same(f+10,peer,6)||!same(f+16,peer,6)||(le16(f+22)&15))return -1;
 StaEvent v={0};v.completion=e->completion;for(unsigned j=0;j<6;j++)v.peer[j]=peer[j];
 if((fc&0xfc)==0xb0){if(n!=30||le16(f+24)||le16(f+26)!=2)return -1;v.kind=STA_AUTH;v.status=le16(f+28);}
 else if((fc&0xfc)==0x10){if(n<30)return -1;v.kind=STA_ASSOC;v.status=le16(f+26);unsigned aid=le16(f+28);if(!v.status){if((aid&0xc000)!=0xc000||!(aid&0x3fff)||(aid&0x3fff)>2007||!(le16(f+24)&0x10)||!rates(f+30,n-30,native,&v.rates))return -1;v.aid=aid&0x3fff;}}
 else if((fc&0xfc)==0xc0||(fc&0xfc)==0xa0){if(n!=26)return -1;v.kind=STA_DEAUTH;v.status=le16(f+24);}
 else return 0;*out=v;return 1;
}
int sta_begin(StaJoin*s,uint64_t epoch,uint32_t floor,uint8_t vdev,const uint8_t peer[6],const uint8_t own[6],uint8_t wmi,uint8_t htt){if(!s||s->epoch||!epoch||vdev>3||!peer||!own||!mac(peer)||!mac(own)||same(peer,own,6)||!wmi||wmi>=9||!htt||htt>=9||wmi==htt||overlap(s,sizeof(*s),peer,6)||overlap(s,sizeof(*s),own,6))return 0;StaJoin v={0};v.epoch=epoch;v.rx_floor=v.watermark=floor;v.vdev=vdev;v.wmi_endpoint=wmi;v.htt_endpoint=htt;for(unsigned j=0;j<6;j++){v.peer[j]=peer[j];v.own_mac[j]=own[j];}*s=v;return 1;}
int sta_observe(StaJoin*s,uint64_t epoch,const StaEvent*e){if(!s||!e||overlap(s,sizeof(*s),e,sizeof(*e))||s->epoch!=epoch||s->quarantined||!e->completion||e->completion<=s->watermark)return 0;
 if(e->kind==STA_DEAUTH){if(!same(e->peer,s->peer,6))return 0;s->quarantined=1;s->core_completed=0;s->watermark=e->completion;return 1;}
 if(e->kind==STA_PEER_UNMAP){if(!s->mapped||e->peer_id!=s->peer_id)return 0;s->mapped=0;s->quarantined=1;s->core_completed=0;s->watermark=e->completion;return 1;}
 if(e->kind==STA_AUTH){if(s->authenticated||!same(e->peer,s->peer,6))return 0;if(e->status)s->quarantined=1;else s->authenticated=1;}
 else if(e->kind==STA_ASSOC){if(!s->authenticated||s->associated||!same(e->peer,s->peer,6))return 0;if(e->status)s->quarantined=1;else{if(!e->aid||e->aid>2007||!e->rates)return 0;s->associated=1;s->aid=e->aid;}}
 else if(e->kind==STA_PEER_MAP){if(s->mapped||e->peer_id>=2048||e->vdev!=s->vdev||!same(e->peer,s->peer,6))return 0;s->mapped=1;s->peer_id=e->peer_id;}
 else if(e->kind==STA_SEC_IND){if(!s->mapped||!s->associated||!s->pending||e->completion<=s->pending_floor)return 0;if(e->peer_id!=s->peer_id||e->cipher!=6||e->unicast!=s->pending_pairwise){s->quarantined=1;s->core_completed=0;}else if(s->pending_pairwise)s->ptk=1;else{s->gtk=1;s->gtk_index=s->pending_index;}s->pending=0;}
 else return 0;s->watermark=e->completion;return 1;}
int sta_observe_owned(StaJoin*s,uint64_t epoch,const QcaRxEvent*e,uint32_t frequency,uint16_t native,const QcaHttBinding*b,const QcaHttVersion*v){if(!s||!e||!s->epoch||s->epoch!=epoch||overlap(s,sizeof(*s),e,sizeof(*e))||overlap(s,sizeof(*s),b,b?sizeof(*b):0)||overlap(s,sizeof(*s),v,v?sizeof(*v):0))return -1;if(e->pipe==1&&(!b||b->endpoint!=s->htt_endpoint))return -1;StaEvent event={0};int rc=e->pipe==1?sta_decode_htt_bound(e,b,v,&event):e->pipe==2?sta_decode_mgmt(e,s->wmi_endpoint,frequency,s->peer,s->own_mac,native,&event): -1;if(rc!=1)return rc;return sta_observe(s,epoch,&event)?1:0;}
int sta_key_posted(StaJoin*s,uint64_t epoch,uint8_t pair,uint8_t index,uint32_t floor,uint32_t cookie){if(!s||s->epoch!=epoch||s->quarantined||!s->associated||!s->mapped||s->pending||pair>1||!cookie||floor<s->watermark||(pair?(index||s->attempted_pairwise):(!index||index>3||s->attempted_group)))return 0;s->pending=1;s->pending_pairwise=pair;s->pending_index=index;s->pending_floor=floor;s->pending_cookie=cookie;if(pair)s->attempted_pairwise=1;else s->attempted_group=1;return 1;}
void sta_key_ambiguous(StaJoin*s,uint64_t epoch){if(s&&s->epoch==epoch){s->quarantined=1;s->pending=0;s->core_completed=0;}}
int sta_core_state(StaJoin*s,uint64_t epoch,unsigned state){if(!s||s->epoch!=epoch||s->quarantined||state>9)return 0;if(state<7&&(s->ptk||s->gtk||s->pending||s->core_completed)){s->quarantined=1;s->core_completed=0;return 1;}s->core_completed=state==9;if(state==9&&(!s->associated||!s->mapped||!s->ptk||!s->gtk||s->pending)){s->quarantined=1;s->core_completed=0;return 0;}return 1;}
int sta_core_protection(StaJoin*s,uint64_t epoch,const uint8_t peer[6],unsigned type,unsigned key_type){if(!s||!peer||s->epoch!=epoch||s->quarantined||!same(peer,s->peer,6))return 0;if(!type){s->protection=0;return 1;}if(type>3||key_type!=1||!s->ptk)return 0;s->protection=(uint8_t)type;return 1;}
int sta_local_eligibility(const StaJoin*s,uint64_t epoch){return s&&s->epoch==epoch&&s->associated&&s->mapped&&s->ptk&&s->gtk&&s->core_completed&&s->protection==3&&!s->pending&&!s->quarantined;}

int sta_local_eligibility_live(const StaJoin*s,const QcaPersistentNative*p){if(!s||!p||!sta_local_eligibility(s,p->epoch)||p->error||p->stop_latched||p->life.phase!=QCA_RADIO_ACTIVE||p->life.error||p->life.owners.epoch!=p->epoch||p->life.owners.init_ready!=1||p->life.owners.stop_verified||!p->life.owners.mappings||p->life.owners.dma_users!=p->life.owners.mappings||p->life.owners.pci!=1||p->life.owners.wake!=1||p->life.owners.link!=1||p->life.owners.irq!=1||p->life.owners.pin!=1||p->life.owners.bus!=1||p->life.owners.bus_master!=1||p->rx.phase!=QCA_RX_ACTIVE||p->rx.error||p->rx.epoch!=p->epoch||p->rx.life!=&p->life||p->rx.startup!=p->startup||p->rx.htt.endpoint!=s->htt_endpoint||p->rx.htt.op_version!=3||!p->startup)return 0;const QcaWmiStartup*w=p->startup;return w->phase==2&&!w->error&&!w->cancelled&&w->transaction.phase==QCA_INIT_RUNNING&&w->transaction.ready_seen==1&&w->transaction.tx_complete==1&&same(w->transaction.ready.mac,s->own_mac,6)&&w->operating&&!w->operating->error&&w->operating->control.session.phase==QCA_HTC_RUNNING&&w->operating->control.session.wmi.endpoint==s->wmi_endpoint;}
